UPDATE public.curriculum_quiz_questions SET question_text='Un patient a douleur, faiblesse et raideur de l’épaule. Quelle évaluation est pertinente ?',options='[{"text":"Rango de movimiento + músculos débiles o rígidos + movimientos dolorosos","correct":true},{"text":"Uniquement la taille du patient","correct":false},{"text":"Uniquement la tension artérielle","correct":false},{"text":"Uniquement la couleur de peau","correct":false}]'::jsonb,explanation='L’amplitude, la faiblesse/raideur musculaire et les mouvements aggravants font partie des éléments fonctionnels décrits.',metadata='{"difficulty_scale_version":"2026-10-v1"}'::jsonb,updated_at=now() WHERE id='4b8011ac-4244-47da-a9e7-5f9c30c989a7'::uuid AND metadata->>'language_revision'='es-s2-20261030' AND question_text='Caso — Hay dolor, debilidad y rigidez de hombro. ¿Qué dominios de valoración son pertinentes?' AND options='[{"text":"Rango de movimiento + músculos débiles o rígidos + movimientos dolorosos","correct":true},{"text":"Solo talla de la persona","correct":false},{"text":"Solo presión arterial","correct":false},{"text":"Solo color de piel","correct":false}]'::jsonb;
