UPDATE public.curriculum_quiz_questions SET question_text='Pourquoi le passage assis-debout est-il intéressant en évaluation fonctionnelle ?',options='[{"text":"Il combine force, contrôle et équilibre","correct":true},{"text":"Il teste uniquement la vision","correct":false},{"text":"Il mesure uniquement la souplesse des doigts","correct":false},{"text":"Il n’a aucun lien avec la fonction quotidienne","correct":false}]'::jsonb,explanation='Il combine force des membres inférieurs, contrôle du tronc et équilibre dans une tâche quotidienne.',metadata='{"difficulty_scale_version":"2026-10-v1"}'::jsonb,updated_at=now() WHERE id='3c4f08b4-d892-4172-a7e0-864f2584ea04'::uuid AND metadata->>'language_revision'='es-s2-20261030' AND question_text='¿Por qué es útil observar la tarea de sentarse y levantarse?' AND options='[{"text":"Combina fuerza, control y equilibrio","correct":true},{"text":"Evalúa únicamente la visión","correct":false},{"text":"Mide únicamente la flexibilidad de los dedos","correct":false},{"text":"No tiene relación con la función cotidiana","correct":false}]'::jsonb;
UPDATE public.curriculum_quiz_questions SET question_text='Lors d’un passage assis-debout, quel élément est utile à observer ?',options='[{"text":"Utilisation des mains, symétrie et stabilité","correct":true},{"text":"Uniquement le rythme respiratoire au repos","correct":false},{"text":"Uniquement la mobilité du poignet","correct":false},{"text":"Uniquement la sensibilité faciale","correct":false}]'::jsonb,explanation='L’utilisation des mains, la symétrie, la douleur et la stabilité donnent des informations fonctionnelles.',metadata='{"difficulty_scale_version":"2026-10-v1"}'::jsonb,updated_at=now() WHERE id='46f179a9-72f5-46d2-a972-b6d097fe6fa0'::uuid AND metadata->>'language_revision'='es-s2-20261030' AND question_text='Durante la tarea de sentarse y levantarse, ¿qué dato conviene registrar?' AND options='[{"text":"Uso de las manos, simetría y estabilidad","correct":true},{"text":"Solo frecuencia respiratoria en reposo","correct":false},{"text":"Solo movilidad de muñeca","correct":false},{"text":"Solo sensibilidad facial","correct":false}]'::jsonb;
UPDATE public.curriculum_quiz_questions SET question_text='Que signifie « ponerse de pie » ?',options='[{"text":"Se lever","correct":true},{"text":"S’allonger","correct":false},{"text":"Ramper","correct":false},{"text":"Tourner la tête","correct":false}]'::jsonb,explanation='L’expression signifie se mettre debout / se lever.',metadata='{"difficulty_scale_version":"2026-10-v1"}'::jsonb,updated_at=now() WHERE id='bf19fa9f-c8ef-4d7a-bf41-836cbddaee3a'::uuid AND metadata->>'language_revision'='es-s2-20261030' AND question_text='Vocabulario FR/ES — ¿Cuál es el equivalente francés de «ponerse de pie»?' AND options='[{"text":"Se lever","correct":true},{"text":"S’allonger","correct":false},{"text":"Ramper","correct":false},{"text":"Tourner la tête","correct":false}]'::jsonb;
