UPDATE public.curriculum_quiz_questions SET question_text='Un patient lève difficilement le bras. Quelle information est prioritaire pour le kiné ?',options='[{"text":"Observer comment le mouvement est réalisé et sa limitation","correct":true},{"text":"Conclure immédiatement à une lésion précise","correct":false},{"text":"Ignorer la fonction quotidienne","correct":false}]'::jsonb,explanation='Il faut relier l’observation du mouvement à la mobilité et à la fonction.',metadata='{"difficulty_scale_version":"2026-10-v1"}'::jsonb,updated_at=now() WHERE id='0fd25aa0-b309-4e7e-b514-82564da71e8a'::uuid AND metadata->>'language_revision'='es-s2-20261030' AND question_text='Caso — La persona eleva el brazo con dificultad. ¿Qué información funcional conviene recoger?' AND options='[{"text":"Observar cómo realiza el movimiento y su limitación","correct":true},{"text":"Concluir inmediatamente una lesión concreta","correct":false},{"text":"Ignorar la función cotidiana","correct":false}]'::jsonb;
UPDATE public.curriculum_quiz_questions SET question_text='Quel est le premier temps simple de l’examen physique ?',options='[{"text":"L’inspection","correct":true},{"text":"La prescription médicamenteuse","correct":false},{"text":"L’imagerie","correct":false}]'::jsonb,explanation='MedlinePlus définit l’inspection comme l’observation et le premier temps de l’examen physique.',metadata='{"difficulty_scale_version":"2026-10-v1"}'::jsonb,updated_at=now() WHERE id='a6c0b319-cb3b-418b-aca1-29b125437419'::uuid AND metadata->>'language_revision'='es-s2-20261030' AND question_text='¿Qué fase inicial sencilla forma parte de la exploración física?' AND options='[{"text":"La inspección","correct":true},{"text":"Prescripción farmacológica","correct":false},{"text":"Las pruebas de imagen","correct":false}]'::jsonb;
