UPDATE public.curriculum_quiz_questions SET question_text='Quel objectif est le plus fonctionnel pour un patient qui peine à se lever d’une chaise ?',options='[{"text":"Se lever d’une chaise plus facilement et en sécurité","correct":true},{"text":"Apprendre le nombre d’ECTS du cursus","correct":false},{"text":"Mémoriser uniquement le nom des muscles","correct":false}]'::jsonb,explanation='Un objectif fonctionnel décrit une activité concrète du quotidien.',metadata='{"difficulty_scale_version":"2026-10-v1"}'::jsonb,updated_at=now() WHERE id='cf089d29-c9f2-4f42-a3d2-0576e3bb62dd'::uuid AND metadata->>'language_revision'='es-s2-20261030' AND question_text='¿Qué objetivo es más funcional para alguien que tiene dificultad al levantarse de una silla?' AND options='[{"text":"Levantarse de una silla con más facilidad y seguridad","correct":true},{"text":"Aprender el número de ECTS del programa","correct":false},{"text":"Memorizar únicamente el nombre de los músculos","correct":false}]'::jsonb;
